#include "InstitutionRuntime.hpp"
#include <cmath>
namespace elysium::fortress {bool InstitutionRuntime::addCulture(CultureProfile c,std::string&w){if(!c.id){w="invalid culture";return false;}for(auto&[_,v]:c.values)v=std::clamp(std::isfinite(v)?v:0.0,-1.0,1.0);return cultures_.emplace(c.id,std::move(c)).second;}bool InstitutionRuntime::upsert(Institution x,std::string&w){if(!x.id||!x.type){w="invalid institution";return false;}if(x.culture&&!cultures_.count(x.culture)){w="unknown culture";return false;}x.quality=std::max(0.0,x.quality);x.prestige=std::max(0.0,x.prestige);inst_[x.id]=std::move(x);return true;}bool InstitutionRuntime::qualified(StableId id)const{auto i=inst_.find(id);return i!=inst_.end()&&!i->second.rooms.empty()&&!i->second.staff.empty();}std::optional<Institution>InstitutionRuntime::get(StableId id)const{auto i=inst_.find(id);if(i==inst_.end())return std::nullopt;return i->second;}}
